<!doctype html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="color-scheme" content="light">
    <title>{{ $ledger['name'] }} · {{ $period['label'] }}账本报告</title>
    <style>
        :root{--navy:#132238;--ink:#1a293b;--muted:#66758a;--line:#dfe6ee;--paper:#fff;--canvas:#f3f6fa;--income:#087b5c;--income-soft:#e3f5ef;--expense:#b53d51;--expense-soft:#fbedee;--balance:#3f63d8;--balance-soft:#e9eeff;--shadow:0 18px 44px rgba(23,42,68,.09)}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px/1.55 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}a{color:inherit}a:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #ffcb66;outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.shell{max-width:1240px;margin:auto;padding:32px 22px 52px}.hero{position:relative;overflow:hidden;padding:42px;border-radius:24px;color:#fff;background:radial-gradient(circle at 88% 8%,#587ee9 0,transparent 32%),linear-gradient(125deg,#11243d,#263f70);box-shadow:0 22px 48px rgba(18,35,61,.24)}.eyebrow{margin:0 0 11px;color:#c9d8ff;font-size:11px;font-weight:800;letter-spacing:.15em}h1{margin:0;font-size:clamp(29px,5vw,46px);line-height:1.12;letter-spacing:-.045em}.hero-copy{max-width:680px;margin:14px 0 0;color:#dce6ff}.hero-meta,.legend{display:flex;flex-wrap:wrap;gap:10px}.hero-meta{margin-top:25px}.hero-pill{padding:7px 11px;border:1px solid rgba(255,255,255,.18);border-radius:999px;background:rgba(0,0,0,.15);font-size:13px}.period-nav,.panel,.metric,.mini-metric{border:1px solid var(--line);background:var(--paper);box-shadow:0 8px 20px rgba(23,42,68,.04)}.period-nav{display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center;padding:18px 21px;margin-top:20px;border-radius:18px}.period-label,.subtle{display:block;color:var(--muted);font-size:12px;font-weight:700;letter-spacing:.04em}.period-current{font-size:19px}.period-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}.button,.period-select{min-height:38px;padding:8px 12px;border:1px solid #cfd9e5;border-radius:9px;background:#fff;color:#29405c;font:700 13px inherit;text-decoration:none}.button.primary{border-color:#294d91;background:#294d91;color:#fff}.button.disabled{opacity:.48}.summary,.grid{display:grid;gap:16px}.summary{grid-template-columns:repeat(3,1fr);margin-top:20px}.metric{padding:22px;border-radius:17px;border-top:4px solid var(--balance)}.metric.income{border-top-color:var(--income)}.metric.expense{border-top-color:var(--expense)}.metric-label{font-weight:800}.metric-value{margin-top:8px;font-size:clamp(23px,3vw,32px);font-weight:850;letter-spacing:-.04em}.metric-note{margin:7px 0 0;color:var(--muted);font-size:13px}.mini-metrics{display:flex;gap:12px;margin:16px 0}.mini-metric{flex:1;padding:13px 17px;border-radius:13px}.mini-metric span,.description,.entry-date{display:block;color:var(--muted);font-size:12px}.panel{padding:24px;border-radius:18px;margin-top:20px}.panel-head{display:flex;justify-content:space-between;gap:12px;align-items:baseline;margin-bottom:18px}h2{margin:0;font-size:19px;letter-spacing:-.02em}.performance{background:linear-gradient(125deg,#fff,#f5f8ff)}.comparison-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.comparison-block{padding:17px;border:1px solid var(--line);border-radius:14px}.comparison-label{font-weight:850}.comparison-period{margin-left:7px;color:var(--muted);font-size:12px}.delta-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:13px}.delta{padding:10px;border-radius:10px;background:#f7f9fc}.delta.favorable{background:var(--income-soft)}.delta.unfavorable{background:var(--expense-soft)}.delta strong{display:block;font-size:13px}.delta-value{font-weight:850}.delta-note{color:var(--muted);font-size:11px}.comparison-empty{margin:13px 0 0;color:var(--muted);font-size:13px}.legend{margin-bottom:10px;color:var(--muted);font-size:12px}.legend i{display:inline-block;width:9px;height:9px;margin-right:4px;border-radius:50%;background:var(--income)}.legend .expense i{background:var(--expense)}.legend .balance i{background:var(--balance)}.daily-chart{display:flex;align-items:end;gap:3px;height:190px;padding:12px 0;border-bottom:1px solid var(--line);overflow:hidden}.day{display:grid;flex:1;min-width:8px;gap:5px;align-items:end;height:100%;text-align:center}.day-bars{display:flex;align-items:end;justify-content:center;gap:1px;height:100%}.day-bar{width:30%;min-height:0;border-radius:3px 3px 0 0;background:var(--income)}.day-bar.expense{background:var(--expense)}.day-bar.balance{background:var(--balance)}.day-bar.refund,.day-bar.negative{background-image:repeating-linear-gradient(135deg,rgba(255,255,255,.55) 0 3px,transparent 3px 6px)}.day-label{overflow:hidden;color:var(--muted);font-size:10px;white-space:nowrap}.trend-wrap{margin-top:25px}.trend-chart{display:block;width:100%;height:180px;border-radius:12px;background:#f8faff}.trend-grid{stroke:#dfe6ee;stroke-width:.6}.trend-area{fill:#dce6ff}.trend-line{fill:none;stroke:var(--balance);stroke-width:2.2;vector-effect:non-scaling-stroke}.chart-table{margin-top:18px}.chart-table summary{cursor:pointer;font-weight:750}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:11px;text-align:left;border-bottom:1px solid var(--line);font-size:13px}th{color:var(--muted)}.comparison-chart{display:flex;justify-content:space-around;gap:14px;min-height:245px;padding-top:16px;border-bottom:1px solid var(--line)}.comparison-group{display:grid;grid-template-rows:170px auto;min-width:100px;text-align:center}.group-bars{display:flex;align-items:end;justify-content:center;gap:6px}.group-bar{width:23px;min-height:2px;border-radius:5px 5px 0 0;background:var(--income)}.group-bar.expense{background:var(--expense)}.group-bar.balance{background:var(--balance)}.group-label{padding-top:8px;font-size:12px;font-weight:750}.group-period{color:var(--muted);font-size:11px}.grid{grid-template-columns:repeat(2,1fr)}.composition{display:grid;grid-template-columns:145px 1fr;gap:18px;align-items:center}.donut{position:relative;width:132px;height:132px;border-radius:50%;background:#eef2f7}.donut span{position:absolute;inset:0;border-radius:50%;background:conic-gradient(var(--income) calc(var(--start)*1%),var(--balance) 0 calc(var(--end)*1%),transparent 0);mask:radial-gradient(transparent 0 48%,#000 49%);-webkit-mask:radial-gradient(transparent 0 48%,#000 49%)}.expense .donut span{background:conic-gradient(var(--expense) calc(var(--start)*1%),#dc8e9b 0 calc(var(--end)*1%),transparent 0)}.donut::after{position:absolute;inset:34px;display:grid;place-items:center;border-radius:50%;background:white;content:'分类';font-size:12px;font-weight:800}.ranking-list{display:grid;gap:10px}.rank-row{display:grid;grid-template-columns:22px 1fr auto;gap:8px;align-items:center}.rank-number{font-weight:850;color:var(--muted)}.rank-name{font-weight:700}.rank-amount{grid-column:3;grid-row:1;color:var(--muted);font-size:11px}.rank-track{grid-column:2/4;height:7px;overflow:hidden;border-radius:99px;background:#edf1f6}.rank-track span{display:block;height:100%;border-radius:inherit;background:var(--income)}.expense .rank-track span{background:var(--expense)}.transaction-cards{display:grid;gap:9px;padding:0;margin:0;list-style:none}.transaction-card{display:grid;grid-template-columns:32px 1fr auto;gap:10px;align-items:center;padding:12px;border:1px solid var(--line);border-radius:11px}.transaction-rank{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--income-soft);font-weight:850}.transaction-card.expense .transaction-rank{background:var(--expense-soft)}.transaction-amount.income{color:var(--income)}.transaction-amount.expense{color:var(--expense)}.empty{padding:25px;border-radius:12px;background:#f6f8fb;color:var(--muted)}.empty strong{display:block;color:var(--ink)}footer{padding-top:22px;color:var(--muted);font-size:12px;text-align:center}@media(max-width:760px){.shell{padding:16px 13px 35px}.hero{padding:28px 22px}.period-nav,.summary,.grid,.comparison-grid{grid-template-columns:1fr}.period-actions{justify-content:flex-start}.delta-list{grid-template-columns:1fr}.panel{padding:18px}.composition{grid-template-columns:1fr}.donut{margin:auto}.comparison-chart{overflow:auto;justify-content:flex-start}.daily-chart{gap:2px}.day-label{font-size:0}.day:nth-child(3n) .day-label{font-size:9px}.transaction-card{grid-template-columns:28px 1fr}.transaction-amount{grid-column:2}}@media print{body{background:white}.shell{max-width:none;padding:0}.hero{box-shadow:none}.panel,.metric,.mini-metric,.period-nav{box-shadow:none;break-inside:avoid}.period-nav{display:none}.panel{margin-top:12px}.daily-chart{height:150px}}
    </style>
</head>
<body>
<main class="shell">
    <header class="hero"><p class="eyebrow">MONTHLY BOOKKEEPING REPORT</p><h1>{{ $ledger['name'] }}</h1><p class="hero-copy">{{ $period['label'] }}财务概览 · 以已发生且有效的收支及当期退款为准</p><div class="hero-meta"><span class="hero-pill">报告期间：{{ $period['start'] }} 至 {{ $period['end'] }}</span><span class="hero-pill">币种：{{ $ledger['currency'] }}</span></div></header>
    <nav class="period-nav" aria-label="报告期间导航"><div><span class="period-label">当前报告期间</span><strong class="period-current">{{ $period['label'] }}</strong></div><div class="period-actions">@if ($navigation['previous'])<a class="button" href="{{ $navigation['previous']['url'] }}" aria-label="查看{{ $navigation['previous']['label'] }}，上一期">← 上一期</a>@else<span class="button disabled" aria-disabled="true">← 上一期</span>@endif<label><span class="sr-only">选择报告月份</span><select class="period-select" aria-label="选择报告月份" onchange="if(this.value){location.href=this.value}">@foreach ($navigation['periods'] as $availablePeriod)<option value="{{ $availablePeriod['url'] }}" @selected($availablePeriod['selected'])>{{ $availablePeriod['label'] }}</option>@endforeach</select></label>@if ($navigation['next'])<a class="button" href="{{ $navigation['next']['url'] }}" aria-label="查看{{ $navigation['next']['label'] }}，下一期">下一期 →</a>@else<span class="button disabled" aria-disabled="true">下一期 →</span>@endif<a class="button primary" href="{{ $navigation['base_url'] }}">最新</a></div></nav>
    <section class="summary" aria-label="财务摘要"><article class="metric income"><div class="metric-label">净收入</div><div class="metric-value">{{ $ledger['currency'] }} {{ $totals['income'] }}</div><p class="metric-note">收入已扣除本期退款</p></article><article class="metric expense"><div class="metric-label">净支出</div><div class="metric-value">{{ $ledger['currency'] }} {{ $totals['expense'] }}</div><p class="metric-note">支出已扣除本期退款</p></article><article class="metric"><div class="metric-label">期间结余</div><div class="metric-value">{{ $ledger['currency'] }} {{ $totals['balance'] }}</div><p class="metric-note">净收入减净支出</p></article></section>
    <section class="panel performance" aria-labelledby="performance-heading"><div class="panel-head"><h2 id="performance-heading">收支表现</h2><span class="subtle">↑ 收入/结余上升、支出下降为有利表现</span></div><div class="comparison-grid">@foreach (['month', 'year'] as $comparisonKey)@php($comparisonItem = $comparison[$comparisonKey])<article class="comparison-block"><strong class="comparison-label">{{ $comparisonItem['label'] }}</strong><span class="comparison-period">对比 {{ $comparisonItem['period_label'] }}</span>@if ($comparisonItem['available'])<div class="delta-list">@foreach ($comparisonItem['metrics'] as $metric)<div class="delta {{ $metric['tone'] }}"><strong>{{ $metric['label'] }}</strong><span class="delta-value">{{ $metric['trend'] === 'up' ? '↑' : ($metric['trend'] === 'down' ? '↓' : '→') }} {{ $metric['message'] }}</span><span class="delta-note">差额 {{ $ledger['currency'] }} {{ $metric['delta'] }}</span></div>@endforeach</div>@else<p class="comparison-empty">{{ $comparisonItem['metrics'][0]['message'] }}</p>@endif</article>@endforeach</div></section>
    <section class="mini-metrics" aria-label="活动指标"><div class="mini-metric"><strong>{{ $daily['active_entries'] }} 笔</strong><span>有效收支记录（按发生日期计入本期）</span></div><div class="mini-metric"><strong>{{ $daily['active_days'] }} 天</strong><span>有有效收支或退款活动的日期</span></div></section>
    <section class="panel" aria-labelledby="daily-flow-heading"><div class="panel-head"><h2 id="daily-flow-heading">每日净现金流</h2><span class="subtle">完整 {{ count($daily['rows']) }} 天 · 退款按发生日冲减</span></div><div class="legend" aria-label="图例"><span><i></i>净收入</span><span class="expense"><i></i>净支出</span><span class="balance"><i></i>日结余</span><span>斜纹：退款冲减或负结余</span></div><div class="daily-chart" role="img" aria-label="每日净现金流柱状图，详细数据见下方表格">@foreach ($daily['rows'] as $day)<div class="day" aria-label="{{ $day['date'] }}：净收入 {{ $ledger['currency'] }} {{ $day['income'] }}，净支出 {{ $ledger['currency'] }} {{ $day['expense'] }}，日结余 {{ $ledger['currency'] }} {{ $day['balance'] }}"><div class="day-bars"><span class="day-bar income {{ $day['income_is_refund'] ? 'refund' : '' }}" style="height:{{ $day['income_height'] }}%"></span><span class="day-bar expense {{ $day['expense_is_refund'] ? 'refund' : '' }}" style="height:{{ $day['expense_height'] }}%"></span><span class="day-bar balance {{ $day['balance_is_negative'] ? 'negative' : '' }}" style="height:{{ $day['balance_height'] }}%"></span></div><span class="day-label">{{ $day['label'] }}</span></div>@endforeach</div><div class="trend-wrap"><div class="panel-head"><h2>累计结余趋势</h2><span class="subtle">每日结余累计，包含退款影响</span></div><svg class="trend-chart" viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="本月累计结余趋势图"><path class="trend-grid" d="M0 25H100M0 50H100M0 75H100"></path><polygon class="trend-area" points="{{ $daily['trend_area'] }}"></polygon><polyline class="trend-line" points="{{ $daily['trend_points'] }}"></polyline></svg></div><details class="chart-table"><summary>查看每日净现金流数据表</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>净收入</th><th>净支出</th><th>日结余</th></tr></thead><tbody>@foreach ($daily['rows'] as $day)<tr><td>{{ $day['date'] }}</td><td>{{ $ledger['currency'] }} {{ $day['income'] }}</td><td>{{ $ledger['currency'] }} {{ $day['expense'] }}</td><td>{{ $ledger['currency'] }} {{ $day['balance'] }}</td></tr>@endforeach</tbody></table></div></details></section>
    <section class="panel" aria-labelledby="comparison-chart-heading"><div class="panel-head"><h2 id="comparison-chart-heading">月度对比</h2><span class="subtle">本期、上月与去年同月的净额</span></div>@if ($comparison['chart']['available'])<div class="legend"><span><i></i>净收入</span><span class="expense"><i></i>净支出</span><span class="balance"><i></i>期间结余</span></div><div class="comparison-chart" role="img" aria-label="月度收入、支出及结余对比柱状图">@foreach ($comparison['chart']['groups'] as $group)<div class="comparison-group"><div class="group-bars"><span class="group-bar" style="height:{{ $group['income_height'] }}%" title="净收入 {{ $group['income'] }}"></span><span class="group-bar expense" style="height:{{ $group['expense_height'] }}%" title="净支出 {{ $group['expense'] }}"></span><span class="group-bar balance" style="height:{{ $group['balance_height'] }}%" title="期间结余 {{ $group['balance'] }}"></span></div><div class="group-label">{{ $group['label'] }}<span class="group-period">{{ $group['period_label'] }}</span></div></div>@endforeach</div><table class="sr-only"><caption>月度对比数据</caption><thead><tr><th>对比期间</th><th>净收入</th><th>净支出</th><th>期间结余</th></tr></thead><tbody>@foreach ($comparison['chart']['groups'] as $group)<tr><th scope="row">{{ $group['label'] }}（{{ $group['period_label'] }}）</th><td>{{ $ledger['currency'] }} {{ $group['income'] }}</td><td>{{ $ledger['currency'] }} {{ $group['expense'] }}</td><td>{{ $ledger['currency'] }} {{ $group['balance'] }}</td></tr>@endforeach</tbody></table>@else<div class="empty"><strong>暂无可比月份</strong>上月或去年同月有有效交易后，将显示月度对比图。</div>@endif</section>
    <div class="grid">@foreach (['income' => '收入', 'expense' => '支出'] as $direction => $label)<section class="panel {{ $direction }}" aria-labelledby="{{ $direction }}-category-heading"><div class="panel-head"><h2 id="{{ $direction }}-category-heading">{{ $label }}分类 Top 10</h2><span class="subtle">视觉组成 · 按净额</span></div>@if (count($categories[$direction]))<div class="composition"><div class="donut" aria-label="{{ $label }}分类占比圆环图">@foreach ($categories[$direction] as $category)<span style="--start:{{ $category['donut_start'] }};--end:{{ $category['donut_end'] }}" title="{{ $category['name'] }} {{ $category['percentage'] }}%"></span>@endforeach</div><div class="ranking-list">@foreach ($categories[$direction] as $index => $category)<div class="rank-row"><span class="rank-number">{{ $category['name'] === '其他' ? '—' : $index + 1 }}</span><span class="rank-name">{{ $category['name'] }}</span><span class="rank-amount">{{ $ledger['currency'] }} {{ $category['amount'] }} · {{ $category['percentage'] }}%</span><div class="rank-track" aria-label="{{ $category['name'] }}占净{{ $label }}{{ $category['percentage'] }}%"><span style="width:{{ $category['bar_percentage'] }}%"></span></div></div>@endforeach</div></div>@else<div class="empty"><strong>本期暂无{{ $label }}分类</strong>有效{{ $label }}或退款产生后将显示组成。</div>@endif</section>@endforeach</div>
    <div class="grid">@foreach (['income' => '收入', 'expense' => '支出'] as $direction => $label)<section class="panel" aria-labelledby="{{ $direction }}-entry-heading"><div class="panel-head"><h2 id="{{ $direction }}-entry-heading">最大{{ $label }}记录 Top 10</h2><span class="subtle">按原始记账金额</span></div>@include('reports.partials.entry-ranking', ['entries' => $rankings[$direction], 'direction' => $direction])</section>@endforeach</div>
    <section class="panel transactions"><div class="panel-head"><h2>近期收支</h2><span class="subtle">按日期倒序，最多 10 笔；作为明细依据</span></div>@if (count($recent))<div class="table-wrap"><table><thead><tr><th>日期</th><th>分类 / 说明</th><th>类型</th><th>金额</th></tr></thead><tbody>@foreach ($recent as $entry)<tr><td>{{ $entry['date'] }}</td><td><strong>{{ $entry['category'] }}</strong>@if ($entry['description'])<span class="description">{{ $entry['description'] }}</span>@endif</td><td>{{ $entry['direction'] === 'income' ? '收入' : '支出' }}</td><td class="transaction-amount {{ $entry['direction'] }}">{{ $ledger['currency'] }} {{ $entry['amount'] }}</td></tr>@endforeach</tbody></table></div>@else<div class="empty"><strong>本期暂无有效收支</strong>当有有效的收入或支出记录时，近期明细会显示在这里。</div>@endif</section>
    <footer>生成于 {{ now()->format('Y-m-d H:i') }} · 此报告为静态 HTML；每次生成报告时均按当前有效账本记录重新生成，更正和退款会同步反映。</footer>
</main>
</body>
</html>
